import { InitializePaymentRequest, KlarnaCheckoutUi } from "@parksandresorts/webapiproxy-types";
import { useMemo, useState } from "react";
import { DibsTheme } from "./nets-hooks";

export const usePaymentStyles = (preferredPaymentProvider: InitializePaymentRequest["paymentProvider"]) => {
  const [stylingRef, setStylingRef] = useState<Element | null>(null);
  const paymentStyling = useMemo((): { klarna?: KlarnaCheckoutUi; nets?: DibsTheme } => {
    if (!stylingRef) {
      return {};
    }

    const computedStyle = getComputedStyle(stylingRef);

    const colorButton = computedStyle.getPropertyValue("--component-klarna-checkout-button-color");
    const colorButtonText = computedStyle.getPropertyValue("--component-klarna-checkout-button-text-color");
    const colorHeader = computedStyle.getPropertyValue("--component-klarna-checkout-heading-color");
    const colorLink = computedStyle.getPropertyValue("--component-klarna-checkout-link-color");
    const radiusBorder = computedStyle.getPropertyValue("--component-klarna-checkout-border-radius");

    const klarna = {
      colorButton,
      colorButtonText,
      colorHeader,
      colorLink,
      radiusBorder,
    };

    const backgroundColor = computedStyle.getPropertyValue("--common-wrapper-background");
    const linkColor = computedStyle.getPropertyValue("--common-color-link");
    const primaryColor = computedStyle.getPropertyValue("--component-primary-button-background");
    const textColor = computedStyle.getPropertyValue("--common-colors-font-body");

    const nets = {
      backgroundColor,
      primaryColor,
      buttonbackgroundColor: primaryColor,
      linkColor,
      textColor,
    };

    return { klarna, nets };
  }, [stylingRef]);

  if (preferredPaymentProvider === "Klarna" || preferredPaymentProvider === "Nets") {
    return { component: <div ref={setStylingRef} />, paymentStyling };
  }

  return { component: null, paymentStyling: undefined };
};
